    output logic       flush,
    output logic       error
);

    always_comb begin
        exec  = 1'b0;
        flush = 1'b0;
        error = 1'b0;

        unique case (cmd)
            8'h01: begin // READ
                case (feature)
                    4'h0, 4'h1: exec = 1'b1;
                    4'hF: begin
                        case (subop)
                            2'b00: exec = 1'b1;
                            default: error = 1'b1;
                        endcase
                    end
                    default: error = 1'b1;
                endcase
            end

            8'h02: begin // WRITE
                case (feature)
                    4'h0: exec = 1'b1;
                    4'hE: flush = 1'b1;
                    default: error = 1'b1;
                endcase
            end

            8'hFF: begin // FLUSH
                flush = 1'b1;
            end

            default: error = 1'b1;
        endcase
    end

endmodule,"module storage_cmd_proc_asserts  (input logic [7:0] cmd,

