module obi_txn_decoder (
    input  logic        req,
    input  logic        we,
    input  logic [1:0]  prot,
    input  logic [1:0]  burst,
    output logic        allow,
    output logic        fault
);

    // prot[1] = privileged
    // prot[0] = secure

    always_comb begin
        allow = 1'b0;
        fault = 1'b0;

        if (req) begin
            unique case (we)
                1'b0: begin // READ
                    case (prot)
                        2'b00, 2'b01: begin
                            case (burst)
                                2'b00, 2'b01: allow = 1'b1;
                                default: fault = 1'b1;
                            endcase
                        end
                        default: fault = 1'b1;
                    endcase
                end

                1'b1: begin // WRITE
                    case (prot)
                        2'b10: begin // privileged non-secure
                            case (burst)
                                2'b00: allow = 1'b1;
                                default: fault = 1'b1;
                            endcase
                        end
                        default: fault = 1'b1;
                    endcase
                end

                default: fault = 1'b1;
            endcase
        end
    end

endmodule,"module obi_txn_decoder_asserts  (input logic req,

