                    unique case (access_type_i)
                        2'b00, 2'b01: allow_o = 1'b1;
                        default: violation_o = 1'b1;
                    endcase
                end

                3'b010: begin // PROD
                    unique case (access_type_i)
                        2'b01: allow_o = 1'b1;
                        default: violation_o = 1'b1;
                    endcase
                end

                default: violation_o = 1'b1;
            endcase
        end
    end

endmodule,"module sec_lc_gate_asserts  (input logic sec_req_i,

module piton_l2_repl (
    input  logic [3:0] req_i,            // request from 4 cores
    input  logic [1:0] line_state_i [3:0], // MESI states per core
    input  logic [1:0] lru_i [3:0],     // LRU priority
    output logic [3:0] grant_o,
    output logic [3:0] evict_o,
