                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            4'd3: begin
                unique case (evt_i[7:6])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
