module tl_axi_obi_bridge (
    input  logic tl_valid_i,
    input  logic [2:0] tl_opcode_i,
    input  logic axi_awvalid_i,
    input  logic axi_arvalid_i,
    input  logic [1:0] obi_resp_i,
    input  logic priv_i,
    output logic tl_a_valid_o,
    output logic [2:0] tl_a_opcode_o,
    output logic obi_req_o,
    output logic obi_we_o,
    output logic [1:0] axi_rresp_o
);

    always_comb begin
        tl_a_valid_o  = 1'b0;
        tl_a_opcode_o = 3'b000;
        obi_req_o     = 1'b0;
        obi_we_o      = 1'b0;
        axi_rresp_o   = 2'b00;

        // TL ? OBI
        if (tl_valid_i) begin
            unique case (tl_opcode_i)
                3'b000: begin
                    tl_a_valid_o  = 1'b1;
                    tl_a_opcode_o = 3'b000; // Get
                    obi_req_o     = 1'b1;
                    obi_we_o      = 1'b0;
                end
                3'b001, 3'b010: begin
                    tl_a_valid_o  = 1'b1;
                    tl_a_opcode_o = tl_opcode_i;
                    obi_req_o     = 1'b1;
                    obi_we_o      = 1'b1;
                end
                default: axi_rresp_o = 2'b11; // DECERR
            endcase
        end

        // AXI ? TL mapping
        unique case (1'b1)
            axi_arvalid_i: begin
                tl_a_valid_o  = 1'b1;
                tl_a_opcode_o = 3'b000; // Get
            end
            axi_awvalid_i: begin
                tl_a_valid_o  = 1'b1;
                tl_a_opcode_o = 3'b001; // PutFull
            end
        endcase

        // OBI ? AXI Response
        unique case (obi_resp_i)
            2'b00: axi_rresp_o = 2'b00; // OKAY
            2'b10: axi_rresp_o = 2'b10; // SLVERR
            default: axi_rresp_o = 2'b11; // DECERR
        endcase

        // Privilege enforcement
        if (!priv_i) begin
            axi_rresp_o = 2'b10;
            tl_a_valid_o = 1'b0;
            obi_req_o    = 1'b0;
        end
    end
endmodule,"module tl_axi_obi_bridge_asserts  (input logic tl_valid_i,

