        out_o = 8'h00;

        case (1'b1)
            sel_i[0]: out_o = mask_i ? 8'h00 : in0_i;
            sel_i[1]: out_o = mask_i ? 8'h00 : in1_i;
            sel_i[2]: out_o = mask_i ? 8'h00 : in2_i;
            sel_i[3]: out_o = mask_i ? 8'h00 : in3_i;
            default: out_o = 8'h00;
        endcase
    end
endmodule,"module chisel_prio_mux_masked_asserts  (input logic [3:0] sel_i,

module sec_lc_gate_priv_mask (
    input  logic sec_req_i,
    input  logic [2:0] lc_state_i,
    input  logic [1:0] access_type_i,
    input  logic priv_i,
    input  logic mask_i,
    output logic allow_o,
    output logic violation_o
);

    always_comb begin
        allow_o = 1'b0;
        violation_o = 1'b0;

        if (sec_req_i) begin
            unique case (lc_state_i)
                3'b000: allow_o = (access_type_i==2'b00 && priv_i && !mask_i);
                3'b001: allow_o = ((access_type_i==2'b00 || access_type_i==2'b01) && priv_i && !mask_i);
                3'b010: allow_o = (access_type_i==2'b01 && priv_i && !mask_i);
                default: violation_o = 1'b1;
            endcase
        end
    end
endmodule,"module sec_lc_gate_priv_mask_asserts  (input logic sec_req_i,
